-- Photo Archive v33 — expiring private links\nalter table private.album_access\n  add column if not exists expires_at timestamptz;\n\ncreate or replace function public.check_album_share_token(\n  target_album_id uuid,\n  supplied_token uuid\n)\nreturns boolean\nlanguage sql\nsecurity definer\nset search_path = ''\nas $$\n  select exists (\n    select 1\n    from private.album_access\n    where album_id = target_album_id\n      and share_token = supplied_token\n      and (expires_at is null or expires_at > now())\n  );\n$$;\n\ncreate or replace function public.get_album_share_info(target_album_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\ndeclare r private.album_access%rowtype;\nbegin\n  if not private.is_gallery_admin() then raise exception 'Not allowed'; end if;\n  select * into r from private.album_access where album_id = target_album_id;\n  return jsonb_build_object('token', r.share_token, 'expires_at', r.expires_at);\nend;\n$$;\n\ncreate or replace function public.set_album_link_expiry(target_album_id uuid, duration_code text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not private.is_gallery_admin() then raise exception 'Not allowed'; end if;\n  update private.album_access set expires_at = case duration_code\n    when '1d' then now() + interval '1 day'\n    when '7d' then now() + interval '7 days'\n    when '30d' then now() + interval '30 days'\n    when '90d' then now() + interval '3 months'\n    when 'never' then null\n    else now() + interval '7 days' end\n  where album_id = target_album_id;\nend;\n$$;\n\ncreate or replace function public.regenerate_album_share_link(target_album_id uuid, duration_code text)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = ''\nas $$\nbegin\n  if not private.is_gallery_admin() then raise exception 'Not allowed'; end if;\n  update private.album_access set\n    share_token = gen_random_uuid(),\n    expires_at = case duration_code\n      when '1d' then now() + interval '1 day'\n      when '7d' then now() + interval '7 days'\n      when '30d' then now() + interval '30 days'\n      when '90d' then now() + interval '3 months'\n      when 'never' then null\n      else now() + interval '7 days' end\n  where album_id = target_album_id;\nend;\n$$;\n\nrevoke all on function public.get_album_share_info(uuid) from public;\nrevoke all on function public.set_album_link_expiry(uuid,text) from public;\nrevoke all on function public.regenerate_album_share_link(uuid,text) from public;\ngrant execute on function public.get_album_share_info(uuid) to authenticated;\ngrant execute on function public.set_album_link_expiry(uuid,text) to authenticated;\ngrant execute on function public.regenerate_album_share_link(uuid,text) to authenticated;\ngrant execute on function public.check_album_share_token(uuid,uuid) to service_role;\n